-- owner_activity
WITH cands AS (SELECT arrayJoin(['airbyte-ai', 'airbyte-app', 'airbyte-dev', 'airbyte-hq', 'airbyte-inc', 'airbyte-io', 'airbyte-labs', 'airbyteai', 'airbyteapp', 'airbytedev', 'airbytehq', 'airbyteinc', 'airbyteio', 'airbytelabs', 'anthropic-ai', 'anthropic-app', 'anthropic-dev', 'anthropic-hq', 'anthropic-inc', 'anthropic-io', 'anthropic-labs', 'anthropicai', 'anthropicapp', 'anthropicdev', 'anthropichq', 'anthropicinc', 'anthropicio', 'anthropiclabs', 'dagster-ai', 'dagster-app', 'dagster-dev', 'dagster-hq', 'dagster-inc', 'dagster-io', 'dagster-labs-ai', 'dagster-labs-app', 'dagster-labs-dev', 'dagster-labs-hq', 'dagster-labs-inc', 'dagster-labs-io', 'dagster-labs-labs', 'dagster-labsai', 'dagster-labsapp', 'dagster-labsdev', 'dagster-labshq', 'dagster-labsinc', 'dagster-labsio', 'dagster-labslabs', 'dagsterai', 'dagsterapp', 'dagsterdev', 'dagsterhq', 'dagsterinc', 'dagsterio', 'dagsterlabs-ai', 'dagsterlabs-app', 'dagsterlabs-dev', 'dagsterlabs-hq', 'dagsterlabs-inc', 'dagsterlabs-io', 'dagsterlabs-labs', 'dagsterlabsai', 'dagsterlabsapp', 'dagsterlabsdev', 'dagsterlabshq', 'dagsterlabsinc', 'dagsterlabsio', 'dagsterlabslabs', 'getairbyte', 'getanthropic', 'getdagster', 'getdagster-labs', 'getdagsterlabs', 'getgitpod', 'getlangchain', 'getn8n', 'getrasa', 'getsentry', 'getshopify', 'gettemporal', 'gettemporal-technologies', 'gettemporaltechnologies', 'gitpod-ai', 'gitpod-app', 'gitpod-dev', 'gitpod-hq', 'gitpod-inc', 'gitpod-io', 'gitpod-labs', 'gitpodai', 'gitpodapp', 'gitpoddev', 'gitpodhq', 'gitpodinc', 'gitpodio', 'gitpodlabs', 'langchain-ai', 'langchain-app', 'langchain-dev', 'langchain-hq', 'langchain-inc', 'langchain-io', 'langchain-labs', 'langchainai', 'langchainapp', 'langchaindev', 'langchainhq', 'langchaininc', 'langchainio', 'langchainlabs', 'n8n-ai', 'n8n-app', 'n8n-dev', 'n8n-hq', 'n8n-inc', 'n8n-io', 'n8n-labs', 'n8nai', 'n8napp', 'n8ndev', 'n8nhq', 'n8ninc', 'n8nio', 'n8nlabs', 'rasa-ai', 'rasa-app', 'rasa-dev', 'rasa-hq', 'rasa-inc', 'rasa-io', 'rasa-labs', 'rasaai', 'rasaapp', 'rasadev', 'rasahq', 'rasainc', 'rasaio', 'rasalabs', 'sentry-ai', 'sentry-app', 'sentry-dev', 'sentry-hq', 'sentry-inc', 'sentry-io', 'sentry-labs', 'sentryai', 'sentryapp', 'sentrydev', 'sentryhq', 'sentryinc', 'sentryio', 'sentrylabs', 'shopify-ai', 'shopify-app', 'shopify-dev', 'shopify-hq', 'shopify-inc', 'shopify-io', 'shopify-labs', 'shopifyai', 'shopifyapp', 'shopifydev', 'shopifyhq', 'shopifyinc', 'shopifyio', 'shopifylabs', 'temporal-ai', 'temporal-app', 'temporal-dev', 'temporal-hq', 'temporal-inc', 'temporal-io', 'temporal-labs', 'temporal-technologies-ai', 'temporal-technologies-app', 'temporal-technologies-dev', 'temporal-technologies-hq', 'temporal-technologies-inc', 'temporal-technologies-io', 'temporal-technologies-labs', 'temporal-technologiesai', 'temporal-technologiesapp', 'temporal-technologiesdev', 'temporal-technologieshq', 'temporal-technologiesinc', 'temporal-technologiesio', 'temporal-technologieslabs', 'temporalai', 'temporalapp', 'temporaldev', 'temporalhq', 'temporalinc', 'temporalio', 'temporallabs', 'temporaltechnologies-ai', 'temporaltechnologies-app', 'temporaltechnologies-dev', 'temporaltechnologies-hq', 'temporaltechnologies-inc', 'temporaltechnologies-io', 'temporaltechnologies-labs', 'temporaltechnologiesai', 'temporaltechnologiesapp', 'temporaltechnologiesdev', 'temporaltechnologieshq', 'temporaltechnologiesinc', 'temporaltechnologiesio', 'temporaltechnologieslabs', 'tryairbyte', 'tryanthropic', 'trydagster', 'trydagster-labs', 'trydagsterlabs', 'trygitpod', 'trylangchain', 'tryn8n', 'tryrasa', 'trysentry', 'tryshopify', 'trytemporal', 'trytemporal-technologies', 'trytemporaltechnologies', 'useairbyte', 'useanthropic', 'usedagster', 'usedagster-labs', 'usedagsterlabs', 'usegitpod', 'uselangchain', 'usen8n', 'userasa', 'usesentry', 'useshopify', 'usetemporal', 'usetemporal-technologies', 'usetemporaltechnologies']) AS login)
SELECT tupleElement(p, 1) AS login,
  countIf(tupleElement(p, 2) = 1) AS n_events,
  if(n_events > 0, formatDateTime(minIf(created_at, tupleElement(p, 2) = 1), '%Y-%m-%d %H:%i:%S', 'UTC'), '') AS first_event_ts,
  if(n_events > 0, formatDateTime(maxIf(created_at, tupleElement(p, 2) = 1), '%Y-%m-%d %H:%i:%S', 'UTC'), '') AS last_event_ts,
  countIf(tupleElement(p, 2) = 2) AS n_actor_events,
  countIf(tupleElement(p, 2) = 2 AND event_type NOT IN ('ForkEvent', 'PublicEvent', 'MemberEvent', 'TeamAddEvent', 'Event', 'SponsorshipEvent')) AS n_personal_actor_events
FROM (SELECT created_at, event_type,
         arrayJoin(if(match(lower(actor_login), '(\\[bot\\]$|-bot$|^dependabot|^renovate|^github-actions|^greenkeeper)'),
                      [(lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')), 3), (lower(actor_login), 2)],
                      [(lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')), 1), (lower(actor_login), 2)])) AS p
  FROM github_events
  WHERE lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')) IN (SELECT login FROM cands) OR lower(actor_login) IN (SELECT login FROM cands))
WHERE tupleElement(p, 1) IN (SELECT login FROM cands)
GROUP BY login
ORDER BY login
LIMIT 500001
FORMAT TSVWithNames
